// Fixture batch 154: probes: dimensioned circles and tangent lines settling. Generated by tools/fixtures/gen-batch-154.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// A sketch's solved curves: lines as their ends, circles as centre and radius; sorted (batch 150).
function sketchProbe(context is Context, sketchId is Id) returns array
{
    var out = [];
    for (var e in evaluateQuery(context, qOwnedByBody(qBodyType(qCreatedBy(sketchId, EntityType.BODY), BodyType.WIRE), EntityType.EDGE)))
    {
        const c = evCurveDefinition(context, { "edge" : e });
        const a = evEdgeTangentLine(context, { "edge" : e, "parameter" : 0 }).origin;
        const b = evEdgeTangentLine(context, { "edge" : e, "parameter" : 1 }).origin;
        const r = function(x) { return round(x / millimeter * 1e6) / 1e6; };
        if (c is Line)
            out = append(out, [1e9 + r(a[0]) * 1000 + r(a[1]), ["line", r(a[0]), r(a[1]), r(b[0]), r(b[1])]]);
        else if (c is Circle)
            out = append(out, [r(c.coordSystem.origin[0]) * 1000 + r(c.coordSystem.origin[1]), ["circle", r(c.coordSystem.origin[0]), r(c.coordSystem.origin[1]), r(c.radius)]]);
    }
    return mapArray(sort(out, function(a, b) { return a[0] - b[0]; }), function(x) { return x[1]; });
}

// sketch: two dimensioned circles, then one line drawn a little off held tangent to both
export function c001(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 15 * millimeter });
    skCircle(s, "c2", { "center" : vector(30, 0) * millimeter, "radius" : 8 * millimeter });
    skLineSegment(s, "l1", { "start" : vector(3.7, 14.486) * millimeter, "end" : vector(31.667, 7.879) * millimeter });
    skConstraint(s, "t1", { "constraintType" : ConstraintType.TANGENT, "localFirst" : "l1", "localSecond" : "c1" });
    skConstraint(s, "t2", { "constraintType" : ConstraintType.TANGENT, "localFirst" : "l1", "localSecond" : "c2" });
    skConstraint(s, "r1", { "constraintType" : ConstraintType.RADIUS, "localFirst" : "c1", "length" : 15 * millimeter });
    skConstraint(s, "r2", { "constraintType" : ConstraintType.RADIUS, "localFirst" : "c2", "length" : 8 * millimeter });
    skSolve(s);
    return { "curves" : sketchProbe(context, id + "s") };
}

